/* Token Radar — dark radar theme: deep ink, amber signal, teal growth. */
:root {
  --bg: #0a0f1c;
  --bg2: #0d1526;
  --panel: #111b30;
  --panel2: #16213a;
  --line: #22304f;
  --text: #e8edf7;
  --muted: #93a0b8;
  --faint: #5f6d88;
  --amber: #f0b429;
  --amber-dim: #8a6d1f;
  --teal: #2dd4bf;
  --red: #f97066;
  --green: #4ade80;
  --radius: 10px;
}
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.55 -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}
.wrap { max-width: 1080px; margin: 0 auto; padding: 0 20px; }
a { color: var(--amber); }

/* ---- header ---- */
.top {
  background:
    radial-gradient(700px 260px at 18% -40px, rgba(240,180,41,.20), transparent 60%),
    radial-gradient(600px 240px at 85% -60px, rgba(45,212,191,.14), transparent 60%),
    var(--bg2);
  border-bottom: 1px solid var(--line);
  padding: 34px 0 26px;
}
.eyebrow {
  margin: 0 0 8px;
  color: var(--amber);
  font-size: 12px;
  letter-spacing: .14em;
  text-transform: uppercase;
  font-weight: 700;
}
.top h1 {
  margin: 0 0 10px;
  font-size: 44px;
  line-height: 1.05;
  letter-spacing: -.02em;
}
.lede { margin: 0; font-size: 17px; max-width: 760px; color: #d5dcee; }
.note { margin: 10px 0 0; font-size: 13px; color: var(--muted); max-width: 760px; }

/* ---- stats ---- */
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin: 22px 0 4px;
}
.stat {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px 16px 12px;
}
.stat b { display: block; font-size: 26px; line-height: 1.15; letter-spacing: -.01em; }
.stat span { color: var(--muted); font-size: 12.5px; }
.stat.hot b { color: var(--amber); }

/* ---- controls ---- */
.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: end;
  margin: 18px 0 6px;
  padding: 14px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}
.ctl { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--muted); font-weight: 600; }
.ctl.search { flex: 1 1 220px; }
.ctl input, .ctl select {
  background: var(--bg2);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 8px 10px;
  font: inherit;
  min-width: 0;
}
.ctl input:focus, .ctl select:focus { outline: 2px solid var(--amber); outline-offset: 1px; }
.ctl.check { flex-direction: row; align-items: center; gap: 7px; padding-bottom: 9px; color: var(--text); font-weight: 500; }
.ctl.check input { width: 16px; height: 16px; accent-color: var(--amber); }
.count { color: var(--muted); font-size: 13px; margin: 10px 2px 12px; }

/* ---- board table ---- */
.board { width: 100%; border-collapse: collapse; font-size: 14px; }
.board thead th {
  text-align: left;
  color: var(--muted);
  font-size: 11.5px;
  text-transform: uppercase;
  letter-spacing: .08em;
  padding: 10px 10px;
  border-bottom: 2px solid var(--line);
  position: sticky;
  top: 0;
  background: var(--bg);
}
.board td { padding: 9px 10px; border-bottom: 1px solid var(--line); vertical-align: middle; }
.board tbody tr { cursor: pointer; }
.board tbody tr:hover { background: var(--panel); }
.board tbody tr.active { background: var(--panel2); }
.board tbody tr.active td:first-child { box-shadow: inset 3px 0 0 var(--amber); }
.num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rank { font-weight: 700; color: var(--amber); }
.rank.top3 {
  display: inline-block; min-width: 26px; text-align: center;
  background: var(--amber); color: #171203; border-radius: 6px; padding: 1px 5px;
}
.pname { font-weight: 650; }
.pslug { color: var(--faint); font-size: 12px; }
.tag {
  display: inline-block;
  margin-left: 7px;
  padding: 1px 6px;
  border-radius: 20px;
  background: rgba(240,180,41,.16);
  color: var(--amber);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  vertical-align: 1px;
}
.chains { color: var(--muted); font-size: 13px; max-width: 170px; }
.bar { display: inline-block; height: 6px; border-radius: 3px; background: var(--amber); vertical-align: middle; margin-right: 8px; min-width: 2px; }
.up { color: var(--green); }
.down { color: var(--red); }
.flat { color: var(--muted); }
.empty { padding: 26px; text-align: center; color: var(--muted); }

/* ---- detail ---- */
.detail {
  background: var(--panel);
  border: 1px solid var(--line);
  border-left: 4px solid var(--amber);
  border-radius: var(--radius);
  padding: 14px 20px 16px;
  margin: 6px 0 20px;
}
.detail h2 { margin: 0; font-size: 24px; letter-spacing: -.01em; }
.detail .sub { color: var(--muted); margin: 2px 0 10px; font-size: 13.5px; }
.detail .back { display: inline-block; margin-bottom: 8px; font-size: 13px; text-decoration: none; }
.dgrid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 10px; }
.dcell { background: var(--bg2); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }
.dcell b { display: block; font-size: 18px; font-variant-numeric: tabular-nums; }
.dcell span { color: var(--muted); font-size: 12px; }
.factors { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 4px; }
.factor { background: var(--bg2); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }
.factor b { display: block; font-size: 17px; font-variant-numeric: tabular-nums; }
.factor span { color: var(--muted); font-size: 12px; }
.factor small { display: block; color: var(--faint); font-size: 11.5px; margin-top: 2px; }
.why { margin: 8px 0 10px; color: #d5dcee; font-size: 14.5px; }
.detail h3 { margin: 10px 0 8px; font-size: 16px; }
.steps { margin: 0; padding: 0; list-style: none; counter-reset: step; }
.steps li {
  counter-increment: step;
  position: relative;
  padding: 8px 12px 8px 44px;
  margin-bottom: 6px;
  background: var(--bg2);
  border: 1px solid var(--line);
  border-radius: 8px;
}
.steps li::before {
  content: counter(step);
  position: absolute; left: 12px; top: 8px;
  width: 24px; height: 24px; line-height: 24px; text-align: center;
  background: var(--amber); color: #171203; border-radius: 50%;
  font-weight: 800; font-size: 13px;
}
.steps li b { color: var(--amber); }

/* ---- live + method ---- */
.live { margin-top: 34px; }
.live h2, .method h2 { font-size: 21px; margin: 0 0 8px; letter-spacing: -.01em; }
.live p, .method p { color: #c6cede; max-width: 820px; }
.live-table tbody tr { cursor: default; }
.method { margin: 34px 0 8px; padding: 20px 22px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); }
.method ul { margin: 0 0 12px; padding-left: 20px; }
.method li { margin-bottom: 7px; color: #c6cede; }
.method li strong { color: var(--text); }
.source { color: var(--faint); font-size: 12.5px; word-break: break-word; }
.foot { border-top: 1px solid var(--line); margin-top: 30px; padding: 18px 0 26px; color: var(--faint); font-size: 13px; }

@media (max-width: 760px) {
  .stats, .dgrid, .factors { grid-template-columns: repeat(2, 1fr); }
  .top h1 { font-size: 34px; }
  .chains { display: none; }
  .board th:nth-child(4), .board td:nth-child(4) { display: none; }
}
